import { nanoid } from "nanoid";
import { waitUntil } from "@vercel/functions";
import { getPool } from "./db.js";
import { mapWithConcurrency, planCourse, writePlannedLesson } from "./aiCourseGeneration.js";
import { MAX_GENERATED_LESSONS } from "./lessonPlanning.js";
import { segmentSource } from "./sourceSegments.js";
import { indexTopicSource, planEntrySource, saveTopic } from "./topicWrites.js";

// Lessons are generated by background jobs (generation_jobs), never inside a
// request. A "course" job plans the course if it has no plan yet, then writes
// its pending lessons up to MAX_GENERATED_LESSONS; a "lessons" job writes or
// rewrites the plan entries it lists (Regenerate, or parts not written yet).
//
// A worker claims a job with a short lease and renews it while it works. Each
// lesson is saved as soon as it is written, so the course can be opened at
// its first lesson. On Vercel a worker stops starting lessons before the
// function's time limit and puts the job back in the queue; a worker that is
// killed lets its lease run out. Either way the next worker resumes the job
// where it stopped. Workers start from kickGenerationWorker, and status reads
// (the upload and course polls) restart a job nobody is working on.

const LEASE_SECONDS = 90;
const LEASE_RENEW_MS = 30_000;
// Lessons written at the same time by one worker.
const LESSON_CONCURRENCY = 3;
// No new lesson starts after this long, so lessons in flight finish inside a
// 300 s function. Off Vercel a worker runs until the job is done.
const START_BUDGET_MS = process.env.VERCEL
    ? Number(process.env.GENERATION_JOB_START_BUDGET_MS || 150_000)
    : Infinity;
// A job whose workers keep dying is given up after this many claims.
const MAX_ATTEMPTS = 6;
// A queued job untouched for this long has no worker coming.
const QUEUED_STALE_SECONDS = 10;

const parseJson = (value, fallback) => {
    if (value == null) return fallback;
    if (typeof value !== "string") return value;
    try {
        return JSON.parse(value);
    } catch {
        return fallback;
    }
};

const errorText = (error) => String(error?.message || error || "Unknown error").slice(0, 300);

// Mirrors the job's stage onto the upload row for the upload page.
const setUploadStep = async (db, uploadId, step) => {
    if (!uploadId) return;
    await db.query(
        `UPDATE uploads SET processing_step = $2, updated_at = NOW() WHERE id = $1 AND status = 'ready'`,
        [uploadId, step],
    ).catch(() => {});
};

// Queues a job for a course. Only one job per course is queued or running:
// a "lessons" request while one is active adds its plan entries to it, and a
// "course" request returns the active job.
export const enqueueGenerationJob = async ({ courseId, userId, uploadId = null, kind = "course", planIndexes = [] }, { db = getPool() } = {}) => {
    const indexes = [...new Set(planIndexes.filter(Number.isInteger))];
    try {
        const inserted = await db.query(
            `INSERT INTO generation_jobs (id, course_id, user_id, upload_id, kind, plan_indexes)
             VALUES ($1, $2, $3, $4, $5, $6::jsonb)
             RETURNING *`,
            [nanoid(), courseId, userId, uploadId, kind, JSON.stringify(indexes)],
        );
        return inserted.rows[0];
    } catch (error) {
        if (error?.code !== "23505") throw error;
    }
    const merged = await db.query(
        `UPDATE generation_jobs
         SET plan_indexes = (
                SELECT COALESCE(jsonb_agg(DISTINCT value), '[]'::jsonb)
                FROM jsonb_array_elements(plan_indexes || $2::jsonb)
             ),
             updated_at = NOW()
         WHERE course_id = $1 AND status IN ('queued', 'running')
         RETURNING *`,
        [courseId, JSON.stringify(kind === "lessons" ? indexes : [])],
    );
    return merged.rows[0] || null;
};

// Claims the given job, or the oldest due one: queued, or running with an
// expired lease. Returns null when there is none.
export const claimGenerationJob = async ({ jobId = null } = {}, { db = getPool() } = {}) => {
    const result = await db.query(
        `UPDATE generation_jobs
         SET status = 'running',
             attempts = attempts + 1,
             locked_until = NOW() + make_interval(secs => $2),
             updated_at = NOW()
         WHERE id = (
            SELECT id FROM generation_jobs
            WHERE (status = 'queued' OR (status = 'running' AND locked_until < NOW()))
              AND ($1::text IS NULL OR id = $1)
            ORDER BY created_at
            LIMIT 1
            FOR UPDATE SKIP LOCKED
         )
         RETURNING *`,
        [jobId, LEASE_SECONDS],
    );
    return result.rows[0] || null;
};

const setEntry = (db, courseId, planIndex, patch) => db.query(
    `UPDATE courses
     SET lesson_plan = jsonb_set(lesson_plan, ARRAY[$2::text], (lesson_plan -> $3::int) - 'error' || $4::jsonb),
         updated_at = NOW()
     WHERE id = $1`,
    [courseId, String(planIndex), planIndex, JSON.stringify(patch)],
);

const courseQuizPrompts = async (db, courseId) => {
    const result = await db.query(
        `SELECT topic_id, prompt FROM questions
         WHERE course_id = $1 AND COALESCE(surface, 'quiz') IN ('quiz', 'exam')`,
        [courseId],
    );
    return result.rows.map((row) => ({ topicId: row.topic_id, prompt: row.prompt }));
};

const inTransaction = async (db, work) => {
    const client = await db.connect();
    try {
        await client.query("BEGIN");
        const result = await work(client);
        await client.query("COMMIT");
        return result;
    } catch (error) {
        await client.query("ROLLBACK").catch(() => {});
        throw error;
    } finally {
        client.release();
    }
};

// The course without the model: every lesson is its source text.
const saveHeuristicCourse = async (db, { course, curriculum, text }) => {
    const plan = curriculum.plan || [];
    const saved = await inTransaction(db, async (client) => {
        await client.query(`DELETE FROM topics WHERE course_id = $1`, [course.id]);
        const topics = [];
        for (const [index, spec] of curriculum.topics.entries()) {
            const sortOrder = Number.isInteger(spec.planIndex) ? spec.planIndex : index;
            const topicId = await saveTopic(client, {
                courseId: course.id, userId: course.user_id, uploadId: course.upload_id, spec, sortOrder,
            });
            topics.push({ topicId, planIndex: spec.planIndex });
        }
        const topicByPlanIndex = new Map(topics.map((topic) => [topic.planIndex, topic.topicId]));
        const lessonPlan = plan.map((entry, index) => ({
            title: entry.title,
            kind: entry.kind || null,
            start: entry.start,
            end: entry.end,
            chars: entry.chars,
            status: topicByPlanIndex.has(index) ? "written" : "pending",
            topicId: topicByPlanIndex.get(index) || null,
        }));
        await client.query(
            `UPDATE courses
             SET status = 'ready', lesson_plan = $2::jsonb, generation_backend = 'heuristic',
                 description = 'Generated from your upload', updated_at = NOW()
             WHERE id = $1`,
            [course.id, JSON.stringify(lessonPlan)],
        );
        return { topics, lessonPlan };
    });
    for (const { topicId, planIndex } of saved.topics) {
        await indexTopicSource({
            topicId, courseId: course.id, uploadId: course.upload_id, userId: course.user_id,
            content: planEntrySource(saved.lessonPlan[planIndex], text),
        });
    }
};

const finishJob = (db, jobId, status, error = null) => db.query(
    `UPDATE generation_jobs
     SET status = $2, error = $3, locked_until = NULL, updated_at = NOW(),
         finished_at = CASE WHEN $2 IN ('done', 'failed') THEN NOW() ELSE NULL END
     WHERE id = $1`,
    [jobId, status, error],
);

// A course is ready once its job is done and it has lessons; with none, it
// failed and can only be regenerated.
const settleCourse = async (db, course) => {
    const { rows } = await db.query(`SELECT COUNT(*)::int AS count FROM topics WHERE course_id = $1`, [course.id]);
    const status = rows[0].count > 0 ? "ready" : "failed";
    await db.query(`UPDATE courses SET status = $2, updated_at = NOW() WHERE id = $1`, [course.id, status]);
    await setUploadStep(db, course.upload_id, "ready");
    return status;
};

// The plan entries a job writes: a course job writes the pending entries
// among the first MAX_GENERATED_LESSONS (the rest wait until the student asks
// for them); a lessons job writes the entries it lists.
export const jobTargetIndexes = (job, plan) => (job.kind === "lessons"
    ? parseJson(job.plan_indexes, []).filter((index) => Number.isInteger(index) && plan[index])
    : plan.map((_, index) => index)
        .filter((index) => index < MAX_GENERATED_LESSONS && plan[index]?.status === "pending"));

// Runs a claimed job. Returns { status: "done" | "requeued" | "failed",
// written, failed }. chat and aiEnabled are injectable for tests.
export const runGenerationJob = async (job, {
    db = getPool(),
    chat,
    aiEnabled,
    startBudgetMs = START_BUDGET_MS,
    now = Date.now,
} = {}) => {
    const startedAt = now();
    const renew = setInterval(() => {
        db.query(
            `UPDATE generation_jobs SET locked_until = NOW() + make_interval(secs => $2), updated_at = NOW()
             WHERE id = $1 AND status = 'running'`,
            [job.id, LEASE_SECONDS],
        ).catch(() => {});
    }, LEASE_RENEW_MS);
    renew.unref?.();
    const counts = { written: 0, failed: 0 };
    try {
        const course = (await db.query(
            `SELECT c.*, u.extracted_text, u.file_name
             FROM courses c LEFT JOIN uploads u ON u.id = c.upload_id
             WHERE c.id = $1`,
            [job.course_id],
        )).rows[0];
        if (!course) {
            await finishJob(db, job.id, "failed", "The course no longer exists.");
            return { status: "failed", ...counts };
        }
        const text = String(course.extracted_text || "").trim();
        if (!text) {
            await finishJob(db, job.id, "failed", "The upload has no extracted text.");
            await settleCourse(db, course);
            return { status: "failed", ...counts };
        }
        if (job.attempts > MAX_ATTEMPTS) {
            await finishJob(db, job.id, "failed", "Generation kept stopping before it finished.");
            await settleCourse(db, course);
            return { status: "failed", ...counts };
        }
        const runContext = { userId: course.user_id, courseId: course.id, uploadId: course.upload_id };
        const fileName = course.file_name || course.title;
        const injected = { ...(chat ? { chat } : {}), ...(aiEnabled ? { aiEnabled } : {}) };

        let plan = parseJson(course.lesson_plan, []);
        if (!Array.isArray(plan) || plan.length === 0) {
            await setUploadStep(db, course.upload_id, "structuring");
            const planned = await planCourse({ fileName, extractedText: text, runContext, ...injected });
            if (planned.heuristic) {
                await saveHeuristicCourse(db, { course, curriculum: planned.heuristic, text });
                await setUploadStep(db, course.upload_id, "ready");
                await finishJob(db, job.id, "done");
                return { status: "done", written: planned.heuristic.topics.length, failed: 0 };
            }
            plan = planned.plan.map((entry) => ({
                title: entry.title,
                kind: entry.kind || null,
                start: entry.start,
                end: entry.end,
                chars: entry.chars,
                status: "pending",
                topicId: null,
            }));
            await db.query(
                `UPDATE courses
                 SET lesson_plan = $2::jsonb, generation_backend = $3,
                     description = 'AI-generated from your upload', updated_at = NOW()
                 WHERE id = $1`,
                [course.id, JSON.stringify(plan), planned.provider || "ai"],
            );
        }
        await setUploadStep(db, course.upload_id, "writing");
        const { segments } = segmentSource(text);

        const targets = jobTargetIndexes(job, plan);
        const prompts = await courseQuizPrompts(db, course.id);
        const done = new Set();

        await mapWithConcurrency(targets, LESSON_CONCURRENCY, async (planIndex) => {
            if (now() - startedAt > startBudgetMs) return;
            const entry = plan[planIndex];
            try {
                const spec = await writePlannedLesson({
                    fileName,
                    entry,
                    planIndex,
                    source: planEntrySource(entry, text, segments),
                    existingPrompts: prompts.filter((item) => item.topicId !== entry.topicId).map((item) => item.prompt),
                    runContext,
                    ...(chat ? { chat } : {}),
                });
                const topicId = await inTransaction(db, async (client) => {
                    const id = await saveTopic(client, {
                        topicId: entry.topicId || null,
                        courseId: course.id,
                        userId: course.user_id,
                        uploadId: course.upload_id,
                        spec,
                        sortOrder: planIndex,
                    });
                    await setEntry(client, course.id, planIndex, { status: "written", topicId: id });
                    return id;
                });
                prompts.push(...(spec.questions || [])
                    .filter((question) => question.questionType !== "ordering")
                    .map((question) => ({ topicId, prompt: question.prompt })));
                counts.written += 1;
                await indexTopicSource({
                    topicId,
                    courseId: course.id,
                    uploadId: course.upload_id,
                    userId: course.user_id,
                    content: planEntrySource(entry, text, segments),
                });
            } catch (error) {
                counts.failed += 1;
                console.warn("[generationJobs] lesson failed", { courseId: course.id, planIndex, message: errorText(error) });
                // A lesson being regenerated keeps its current version.
                if (!entry.topicId) {
                    await setEntry(db, course.id, planIndex, { status: "failed", error: errorText(error) });
                }
            }
            done.add(planIndex);
        });

        const remaining = targets.filter((index) => !done.has(index));
        if (remaining.length > 0) {
            await db.query(
                `UPDATE generation_jobs
                 SET status = 'queued', locked_until = NULL, plan_indexes = $2::jsonb, updated_at = NOW()
                 WHERE id = $1`,
                [job.id, JSON.stringify(job.kind === "lessons" ? remaining : [])],
            );
            return { status: "requeued", ...counts };
        }
        await finishJob(db, job.id, "done", counts.failed ? `${counts.failed} lesson(s) could not be written.` : null);
        await settleCourse(db, course);
        return { status: "done", ...counts };
    } catch (error) {
        // Unexpected (database) errors leave the job to its lease: the next
        // worker retries it, up to MAX_ATTEMPTS.
        console.error("[generationJobs] job failed", { jobId: job.id, message: errorText(error) });
        await db.query(`UPDATE generation_jobs SET error = $2, updated_at = NOW() WHERE id = $1`, [job.id, errorText(error)])
            .catch(() => {});
        throw error;
    } finally {
        clearInterval(renew);
    }
};

// Claims and runs one job (the given one, or the oldest due one). A job put
// back in the queue at the time budget starts a fresh worker.
export const processGenerationJob = async ({ jobId = null } = {}, options = {}) => {
    const job = await claimGenerationJob({ jobId }, options);
    if (!job) return null;
    const result = await runGenerationJob(job, options);
    if (result.status === "requeued") kickGenerationWorker({ jobId: job.id });
    return result;
};

// Starts a worker without waiting for it. With GENERATION_WORKER_URL and
// GENERATION_WORKER_SECRET set (production), the worker is a fresh
// invocation of api/generation-worker.js with its own time limit; otherwise
// it runs in this process, kept alive on Vercel by waitUntil.
export const kickGenerationWorker = ({ jobId = null } = {}) => {
    const url = String(process.env.GENERATION_WORKER_URL || "").trim();
    const secret = String(process.env.GENERATION_WORKER_SECRET || "").trim();
    const task = url && secret
        ? fetch(url, {
            method: "POST",
            headers: { Authorization: `Bearer ${secret}`, "Content-Type": "application/json" },
            body: JSON.stringify({ jobId }),
        }).then((response) => response.body?.cancel?.())
        : processGenerationJob({ jobId });
    const guarded = Promise.resolve(task).catch((error) => {
        console.warn("[generationJobs] worker failed to start or run", { jobId, message: errorText(error) });
    });
    waitUntil(guarded);
    return guarded;
};

// Restarts the course's job when no worker is on it: queued for a while, or
// running with an expired lease. Called by status reads, so a course keeps
// moving while anyone is watching it.
export const resumeStalledGeneration = async (courseId, { db = getPool() } = {}) => {
    const { rows } = await db.query(
        `SELECT id FROM generation_jobs
         WHERE course_id = $1
           AND ((status = 'queued' AND updated_at < NOW() - make_interval(secs => $2))
             OR (status = 'running' AND locked_until < NOW()))
         LIMIT 1`,
        [courseId, QUEUED_STALE_SECONDS],
    );
    if (rows[0]) kickGenerationWorker({ jobId: rows[0].id });
    return Boolean(rows[0]);
};

export const activeGenerationJob = async (courseId, { db = getPool() } = {}) => {
    const { rows } = await db.query(
        `SELECT * FROM generation_jobs WHERE course_id = $1 AND status IN ('queued', 'running') LIMIT 1`,
        [courseId],
    );
    return rows[0] || null;
};
